(window.webpackJsonp=window.webpackJsonp||[]).push([[109],{550:function(t,s,v){"use strict";v.r(s);var _=v(11),n=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：以经为尺，以行调知，周而复始，大道可识。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹平安。今天我们继续来讲路加福音7:18~23节的内容。我们一起来读。今天我们的题目是“先验中的神和经验中的神”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这是一段关于施洗约翰的经文。上一次路加福音提到他是在第3章。在路加福音3：19~20节记载，施洗约翰因为责备当时犹太地区的分封王希律娶了兄弟的老婆这件恶事，而被他关在监狱当中。到路加福音第7章这里，有学者估计他已经被囚禁好几个月，甚至超过一年的时间了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从今天的经文第18节我们知道，虽然在被囚期间，但施洗约翰仍然可以和他的门徒们进行接触。而他的门徒们就把主耶稣所做过的这些事告诉给了他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“这些事”，不仅包括了第7:1~10节他医治百夫长仆人的事以及 7:11~17节他使拿因城的一个寡妇的儿子复活的事，还包括了路加福音第4:14节开始记载的耶稣的各种言行。包括他在加利利各处传神国的福音、赶鬼、医治疾病（4:14~44）；他洁净长大麻风的人、治好瘫痪的人（5:12~26）；他呼召税吏、与罪人一同吃喝（5:27~32）；他不按照犹太人的传统禁食、守安息日（5:33~6:11）；以及他教导不要去审判人、要对仇敌施以饶恕和仁爱（6:17~49）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("仅仅从我的这些概述中，大家也许已经能够在心中大致勾勒出主耶稣的一个形象来：他是一个温和的、宽厚的、包容的、有怜悯的人，也是一个不太遵守犹太人宗教规条的人。对不对？我想施洗约翰听到门徒们对主耶稣言行的描述，也会对他形成类似的印象。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但恰恰是这个印象，给施洗约翰带来了困扰。因为他从门徒们描述中所看到的耶稣的形象，与他自己心目中的弥撒亚的形象存在着差异。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("施洗约翰心中的弥撒亚是怎么样的形象呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("首先我们先了解一下施洗约翰自己是什么样的人。在下次我们会涉及到的经文7:33节，耶稣描述施洗约翰是“不吃饼、不喝酒”。马太福音、马可福音中描述施洗约翰住在旷野，穿骆驼毛的衣服，腰束皮袋，吃的是蝗虫、野蜜。另外，根据路加福音第5:33节我们也知道，约翰和他的门徒常常禁食。从这些描述中，我们可以看到：施洗约翰过的是一种严格、自律的苦修宗教生活。不难想见，这种人往往会对各种宗教上的规条严苛地遵守。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而施洗约翰对自己的使命是如何认识的呢？我们来翻到约翰福音第1章。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在约翰福音1:23节，他说“我就是那在旷野有人声喊着说：‘修直主的道路’，正如先知以赛亚所说”。和合本这个翻译有点不太清楚，但我们去看其他译本就知道，他说我自己是个“呼喊的声音”，呼喊人们要预备好主的道路。这有点像我们古代县太爷要审案子，在他出来之前，衙役们要喊叫“威~武~”。原告、被告听到这个声音，就知道县老爷要出场了，就准备好。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以施洗约翰非常清楚，他是为基督到来做准备的那个呼喊声，是为基督来预备人心的。正因为如此，当他认出这位拿撒勒人耶稣就是基督，他就主动把人们引向耶稣那里（约翰福音1:29~36节）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么可想而知，作为一名严格恪守宗教规条的苦修者，他在内心深处，自然也会期待那位他所指明的弥赛亚，和他一样表现出这种严肃与克己的形像。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而耶稣在这里就和他的想象出现了差异。他和他的门徒们并不禁食，也没有严格按照犹太人的规条遵守安息日。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们一起把圣经再翻到路加福音3:16~17，来看一下施洗约翰是如何见证的弥赛亚的。在这段经文中，他说：“我是用水给你们施洗。但有一位能力比我更大的要来，我就是给他解鞋带也不配，他要用圣灵与火给你们施洗。他手里拿着簸箕，要扬净他的场，把麦子收在仓里，把糠用不灭的火烧尽了。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看，施洗约翰的信息，强调了这位在他后面要来的人，是要来扬净打谷场，分开麦子和糠秕，并对后者用火焚烧。这是一幅审判的画面。所以很自然，施洗约翰心目中的弥赛亚，是一位严厉的审判者，他会把神的子民从那些罪恶的人当中召聚出来，并对恶人进行报复、惩治。而主耶稣在他的所言所行中所体现出来的那种温和、宽厚、怜悯的形象，就再次与施洗约翰心目中的弥撒亚出现了差异。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("正是这些差异，使得施洗约翰对这位拿撒勒人的信心产生了动摇。他曾经看到过圣灵降在他身上，他曾经见证说这人就是基督。但现在，当他身陷囹圄，那位他自己认定的弥撒亚，却并没有如他所期待的，立即对这个罪恶的世界展开审判、刑罚那些作恶的、与神为敌的人。相反，耶稣的所言所行，处处与施洗约翰的想象相左：一方面，他在以宽厚、仁慈的心对待这个世界、在教导要爱你的仇敌；另一方面，他没有选择那条远离人群、克己苦修的道路，反而与税吏、罪人同席，在安息日治病，似乎不像是一位“敬虔”的弥赛亚当有的样子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("好，我们翻回到路加福音第7章。于是在路加福音7:19节我们看到，他差门徒去到耶稣那里询问：“你就是那位要来的，还是我们要等别人呢？”他曾经很笃定，这位拿撒勒人耶稣就是那位要来的，因而主动、热情地向别人推荐他。但现在，在一段时间之后，在身陷囹圄之后，在听到了他的言行之后，他发现这个现实中的人与他头脑中的弥撒亚并不一样。于是他开始怀疑自己当初是不是搞错了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果我们用哲学术语来描述：他心中原本有一个关于弥赛亚“先验性”的认识，也就是原来想象的样子；而现在，通过听闻耶稣的言行，他获得了一种“经验性”的认识，就是通过实际观察而认知的样子。这两者如今无法吻合，于是疑惑便产生了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这种现象在我们的信仰生活中是非常常见的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们刚接触基督教的时候，通过听道、读经，总会对神形成一个自己的印象，或者叫做“先验性”的认识。比如认为“神是慈爱的，会赐福给我”，或者“神是大能的，会应允我的祷告”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但当我们实际去经验之后，可能会发现，神似乎和想象中的并不一样。有人为疾病得医治祷告，病却未得痊愈；有人为儿女能怀孕而祷告，却迟迟没有消息；有人恳切求一份工作，却依然求职无门；有人为夫妻和好向神呼求，但最终却婚姻破裂。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这时候，你就获得了对神的一个“经验性”认识。这个认识，可能就与你之前的那种“先验性”认识存在着差异。这种差异，会让你对神产生困惑、怀疑。就我的观察而言，仅仅这一步，就已经让一大批本想要踏上这条信仰之路的慕道友或者初信者，转身离开了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但这现象并非只针对慕道友或者初信者，而是每位信徒一生都在这条信仰之路上不断经历的。每个人都会不断对神形成某种印象、某种认识，然后当实际地在生活中去经验神的带领，又不断发现他从经验中认识的神与他之前先验性认识的神，或者说他想象的神，存在差异。于是就会开始困惑甚至怀疑。如果这种困惑或者怀疑不能得到妥善解决，那么这个人就会从这条信仰之路上离开了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我举两个例子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我认识一位女士，很遗憾，或许如今我已经不能称她为姐妹了。她的丈夫是一个很强势，性情很暴躁的人。后来他们夫妻听了福音，信了主，也一同受了洗、并参加了教会的门徒培训课程。但两三年后，她发现她的丈夫仍然经常在家里发脾气，并且常常拿着圣经经文来指责她的不是，家里甚至总是因为信仰问题争吵。于是她就渐渐远离教会、远离神了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在她身上发生的，就是这样的一个过程。她对神有一个先验性的认识——神会改变自己的丈夫的性情，从而保守自己家庭和睦、夫妻恩爱；但在实际经验之后，她发现神并没有这样做。这时候她从经验中所认识的神，就与她“先验”或“想象”的神出现了差异。正是这个差异，让她陷入困惑，并最终选择了离开。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第二个例子来自于我很喜欢的一位传道人，保罗华许(Pau Washer)。他有一次被邀请去一个教会讲道，宣讲的内容是神的审判。在讲道结束后，有一位老姐妹走到他面前说：“保罗弟兄，你所讲的神不是我认识的神。我认识的神是慈爱的，他不会发怒、也不会审判人。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看，这位姐妹也是对神有一个先验性的、想象中的认识——神是全然慈爱、从不发怒的。而这次听道的经历，却让她接触到一位“会愤怒、施行审判”的神。这个崭新的经验性认识，显然与她心中原有的印象产生了差异。这差异就引起了她的困惑、怀疑。而如果她的这种困惑、怀疑不被妥善处理，她仍然坚持自己原有的想象，拒绝按照她从这场听道经验中所获得认识去调整自己对神的认识，那么她实际上就已经离开这条信仰之路了，因为她所敬拜的，就不是那位真神，而是她想象出的偶像。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在今天的经文中，主耶稣在第23节提醒施洗约翰：“凡不因我跌倒的，就有福了”。这里的“我”，固然是指主耶稣自己。但我想请大家注意，在这个语境中，主耶稣说的这个“我”，更是指向那个客观的、实际的、现在施洗约翰听他门徒的讲述而在经验中所认识的基督，而不是他想象中的那个纯粹主观的、完全先验的基督的样子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("刚才我们已经讲了，施洗约翰想象中的那个纯粹主观的、完全先验的基督，是一位过着苦修生活、坚守清规戒律、严厉施行审判的形象。而现在他所经验到的拿撒勒人耶稣，却显得温和、宽厚、包容、满有怜悯、也不太严格遵守犹太人传统的宗教规条。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果施洗约翰坚持按照他的主观想象去认识基督，也就是弥赛亚，不去根据他现在从经验中所认识的耶稣来调整他原有的认识，那么结果会如何呢？他就会否定耶稣是犹太人在等待的那位基督、那位弥撒亚，那么他就跌倒了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但如果他不固守自己的想象，而是愿意根据从经验中认识的这位拿撒勒人，来调整自己心中弥赛亚的形象呢？他就会继续认定耶稣就是基督——这样，他便“有福了”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，这是我们行走在这条信仰之路上的一个重要心态：你必须允许自己对神、对主的认识、印象或想象，在实际经历中被不断调整。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你可能对神的性情有某种理解，对祂如何安排你的人生有某种期盼，甚至对他要如何使用你有某种“异象”——这些都是你对神一种“先验性”的认识。而随着生活的展开，神驱动万事，让你在具体的际遇中去经历他、体验他，从这些经验中获得的对神的认识，就可能与你之前的认识产生差异。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当我们去妥善地解决这些差异，允许这些经验中的认识来调整我们原有对神的认识，我们就会获得一个更新后的对主的印象或者说想象，一个更新后的先验性的认识；然后，随着我们生活的继续展开，又会有新的经验性认识加入进来。如此周而复始，我们对神的认识也就越来越丰富、越来越完整、越来越客观。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但我们如果执着于自己的先验性认识，拒绝被经验中所获得的认识所调整，也就是说，不去妥善解决这些差异而带来的困惑、怀疑，那么最后你就会跌倒、远离神。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家知道宣教士威廉·博德恩（William Borden）的故事吗？我还记得我第一次读到他的事迹时的感受。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("博德恩出生于一个富裕的美国家庭。耶鲁大学毕业后，进入普林斯顿神学院深造。他自己多次明确表示，他受到了神的呼召，要进入中国甘肃进行宣教。1913年初，他神学院毕业后的次年，就从美国启程，绕道埃及前来中国。然而在开罗短暂停留期间，他不幸感染了脑膜炎，很快在1913年4月就病逝了，年仅25岁，最终未能踏上中国的土地。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我当时读到这里，非常困惑。博德恩不是有清楚的呼召，要来到中国兰州宣教吗？这不是神给他的异象吗？那神为何会让他还没有到中国之前，就去世了呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看，我之所以有这个困惑，就是因为我对神有一个先验性的、主观性的认识，就是神既然呼召了他，那就一定会带他来到甘肃。但随着博德恩旅程的展开，他并未抵达中国就去世了。这就是一个经验，在这经验当中，我获得了对神的一个新的认识：神并没有带他来到中国，没有使用他在甘肃大地上传扬福音。这个经验上的认识就与我之前先验上的认识产生了差异。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在博德恩死后，他的母亲为纪念儿子，捐出一笔巨款，在甘肃首府兰州兴建一所现代医院。这所医院于1915年奠基，1916年建成，命名为 “博德恩纪念医院”（Borden Memorial Hospital），是当时中国西北地区规模最大、设备最先进的西式医院之一。当时这家医院由英国传教组织“中国内地会”（China Inland Mission）负责运营，在抗战时期及后来一直服务于当地民众。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("毫无疑问，这所医院不仅对当地民众的身体带来医治，也成为了一个重要的宣教窗口。在20世纪初的中国，尤其在相对封闭保守的西北地区，直接宣讲福音阻力是非常大的。而这所医院就成为了打开局面的“敲门砖”。宣教士们在这所医院中通过治疗疾病这种切实的、超越文化隔阂的善行，赢得了当地民众的信任和好感，为传教士接触各阶层人群创造了空间。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("读到这里，我自己才重新理解了神对博德恩“去甘肃宣教”的呼召，到底是什么意思。原来不是指博得恩自己去行走在甘肃大地上，而是借着这所“博德恩纪念医院”来让更多的宣教士在这里传扬天国的福音。这也就让我对神自身有了更丰富的认识：他使用人原来不限于某个人活着的时候，也可以在某个人死后使用他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我不知道当时在开罗病床上弥留之际的博德恩是否也会对神有这样的疑问：那差派我去甘肃传教的，是你吗？你真的差派我去甘肃传教吗？但我相信当他死后，躺在神的怀中，看到他的母亲捐出巨资、看到以他命名的医院建成、看到宣教士们在这所医院当中见证基督，他也会和我一样，对神有着更新的、更丰富的认识。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同样，当施洗约翰用在经验中获得的对主耶稣的认识去调整自己那先验性的、想象中的弥撒亚形象，他也将会对弥撒亚有更新的、更丰富的认识：他不仅是行审判的主，他也是有怜悯的、宽厚的主。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，神创造人的目的，就是让人认识他；我们的信仰旅程，就是不断去认识他的过程；无论在今生、在死后、在复活后，我们生命的意义，全在乎认识他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而这个认识的过程，也就是他不断向我们启示他自己的过程。从今天的经文我们看到，他不断通过我们的经验、我们际遇启示他自己。我们要不断认识他，就要谦卑在他面前，允许从这些经验中获得的对神的认识来调整我们观念中固有的对神的认识，这样你才能使自己的困惑、怀疑得到解决，这样你才不会远离神，这样你对神的认识才越来越接近是那个客观的、实际的的样子，而不是你想象中的、纯粹主观的、完全先验的神的样子。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我喜欢用“水与舟”的意象，来比喻我们与神之间的关系。神是世界的创造者与主宰，万物皆在他手中运行，无一不在他的掌管之下。神按自己的旨意，使万象更迭、世事流转——这一切犹如流水，随他的手势而动。而我们，便生活在这流动的万象之中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果我们执着于自己想象中的神、先验中认识的神，那就好比将船牢牢系在一根石柱上。任凭世事如何流动，你的心——你那艘船——都无法随之调整。最终或许只落得浪打船翻。反之，如果我们不固守于那想象中的、全然先验的对神的认识，让我们的心成为一只不系之舟，那么，我们就能随着水的流动而前行。对神的认识，就将在经历中不断更新、丰富，并始终顺着神意的水流，自在地前行。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是我今天要分享的第一点信息，你一定要允许自己对神的认识、印象或者说想象，在你的经验中被调整。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来我想提醒大家的是，对以上我分享的信息一定要正确理解，否则你就可能误入歧途、走火入魔。你可能会误以为我是在讲我们需要“完全”从自身的经验、经历中去获得对神的认识。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不，我不是这个意思。让我们回到今天的经文中，我来继续解释。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("刚才我们已经说了，施洗约翰在经验中认识的耶稣与他想象中的、先验中的弥撒亚发生了差异，他产生了疑惑，于是他派他的门徒去向耶稣询问。那主耶稣是如何回答的呢？在第22节，他说：“你们去，把所看见、所听见的事告诉约翰，就是：瞎子看见，瘸子行走，长大麻风的洁净，聋子听见，死人复活，穷人有福音传给他们。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们仔细来想想，耶稣这个回答，解决施洗约翰的问题了吗？他所说的这些事情，难道在第18节，约翰的门徒们在报告他“这些事”的时候，没有告诉他吗？显然是告诉了。正是因为告诉了，他才会起疑惑，他才会派人去询问。现在耶稣让他们再去告诉他一遍，有何意义呢？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("主耶稣这里的深意，是要提醒施洗约翰，你要注意“经上”是如何预言弥赛亚的。他在这里所提及的这几个事迹，除了洁净大麻风以外，都是旧约圣经上对弥赛亚的预言：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("以赛亚书35:5~6节说“那时瞎子的眼必睁开，聋子的耳必开通。那时瘸子必跳跃像鹿，哑巴的舌头必能歌唱。”以赛亚书61:1节说：“主耶和华的灵在我身上，因为耶和华用膏膏我，叫我传好信息给贫穷的人，差遣我医好伤心的人，报告被掳的得释放、被囚的出监牢。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣这里所提出的“瞎子看见”，“瘸子行走”，“聋子听见”，“死人复活”，“穷人有福音传给他们”，被当时的犹太宗教拉比们普遍认为是弥撒亚来了会行的神迹。而洁净大麻风，我在讲解路加福音5:12~16节的时候也讲过了，一个犹太人得了大麻风后被洁净，在他们进入到应许之地后几千年的时间，就从来没有发生过。因此医治麻风病也被犹太拉比们视为弥撒亚大能的体现，从而被升格为是一个只有弥撒亚会行的神迹。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看，这些在在旧约圣经中被先知们预言的神迹所体现出来的弥撒亚，正是一个温和、宽厚、满有怜悯的形象。对弥撒亚的这种形象，施洗约翰理当非常清楚。既然如此，那么这些形象也理当构成施洗约翰先验中的、主观中的、想象中的弥撒亚形象的一部分。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以主耶稣在这个回答中，实际上是告诉施洗约翰，你不要忘了这部分的内容。你现在从经验中获得的对我的认识，是符合这一部分的内容的；而你现在需要做的，是去把经上的这样的弥赛亚的形象，和你自己头脑中所想象的弥赛亚形象调和起来。如果你能够调整，你就会认识到我是弥撒亚，你就有福了；如果你不能够调整，你就会否认我是弥撒亚，你就跌倒了。所谓调整，这就是一个选择、重构的过程，这里面会涉及到一些新认识的产生，当然也就会涉及到对原有某些认识的抛弃。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们在第一部分讲到，要允许自己对神的认识、印象、想象，在你的经验中被调整。而从主耶稣在路加福音第22节这句回答中我们看到，这个调整是有界限的。这个界限就是神明确的启示——也就是圣经。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("施洗约翰从经验中所认识到的耶稣——那位温柔、宽厚、有怜悯的形象，正是圣经所启示的弥撒亚的形象。而施洗约翰所传讲的那个审判、用火焚烧恶人的形象，如果我们去查考旧约圣经，当然也是弥撒亚的形象。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他之所以对耶稣产生疑惑，恰恰是因为他过于强调了后者而忽略了前者。为什么他会如此？这与他的处境有关。他看到自己身陷牢狱，而恶人却仍在世上横行。他切切期望恶人被审判，而这期望在现实中却迟迟得不到回应。于是，他不耐烦了。这种不耐烦就成为一根石柱，捆住了他的心，让他的心滞留在“审判”这一点上，无法随神的手所推动的世事而流动。结果，可能他自己都没有意识到，他心中弥撒亚那温柔、宽厚的一面被淡化了，而审判、严厉的一面却被强化了。换句话说，他头脑中弥撒亚的形象开始失衡、扭曲了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而当他遵照主耶稣的提醒，去调整自己对弥撒亚的认识，去认真面对旧约圣经中启示的那位既温柔、宽厚、满有怜悯，又严厉施行审判的弥撒亚，他就会意识到，神并不是按他所想象的节奏来审判恶人，所以他的不耐烦不过是从血气来的。同样，当他去认真回到圣经的启示，我相信他也会舍弃掉那种“弥赛亚必须过苦修生活”的想法，因为那根本不是圣经的教导。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当他完成了这样的调整个，他就会对神、对弥撒亚有更丰富的认识。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，我们看到，这样对神认识的调整，不是随意的，不是没有界限的，而是以神清晰的启示为依据的。我们需要臣服在神的启示之下。这就是为什么我在讲完第一点后提醒大家，你不要误认为我是在讲我们要 “完全”从自身的经验、经历中去获得对神、对主的认识。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不，不是这样的。我们对神的认识要根植在神自己明确的启示——也就是这本圣经——当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("圣经是神的启示，是没有错误的、整全的、完美的；但我们对圣经的理解却不是神的启示，里面可能包含了错误、偏狭、不平衡。而我们头脑中对神的那个“先验的”、主观的、想象的印象，正是基于这种不完美的理解而形成的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("随着我们信仰生活的展开，神让我们去经验各种际遇，这些经验可能是你听到的一篇道，可能是你读到的一段经文，可能是你看到的一本书，可能是你遇到了一个人，可能是你遭遇的一场车祸，可能是你经历的一次失业，可能是你被升职加薪，可能是你的祷告蒙了应允，可能是你的祷告不蒙应允，等等等等。在这些经验中，你会获得对神的某种认识。这种认可能与你头脑中的原来的那个认识存在差异，从而使你困惑、怀疑。这时候，你必须正确地去解决这些困惑和怀疑。否则你就会因此跌倒，从而远离神，失去那永远的福分。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而正确解决这些困惑和怀疑的关键，就在于回到圣经，屈服在圣经之下，用你从经验中获得的对神的认识，去调整你头脑中原有的那关于神的先验的、主观的、想象中的印象，从而形成一个更新后的、更丰富的对神先验主观印象。既然这个过程是在圣经的权威下完成的，那么，这个更新之后的对神的认识，就不会离那客观的、真正的神更远，而只会是更近。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我非常喜欢用路加福音11:9~10节的经文来鼓励慕道友：“你们祈求，就给你们；寻找，就寻见；叩门，就给你们开门。因为凡祈求的，就得着；寻找的，就寻见；叩门的，就给他开门。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但偶尔也会遇到一些慕道友来向我抱怨：我祷告祈求认识神，也尽力参加聚会，读经很长时间，却依然感受不到神，无法信靠他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("起初遇到这些问题，我常常无语。这是因为我曾经的印象中，神是迫不及待地回应每一位寻求他的人。所以只要他们真诚地去寻求了、祷告了，都会在不长的时间内感受到神并信靠他。但和这些慕道友的交谈经验，就让我对神产生了与原来不同的印象。这就使我困惑、无言以对。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("此时如果我不回到圣经，不屈服在圣经之下，就无法正确地解决这个困惑。我可能就会在心中构建出一个“不守信的神”的形象来——那其实不是神，而是偶像——并最终导致我自己也远离神。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但感谢神，他使我的心能屈服在圣经之下，重新去思考神的主权、思考这节经文的含义。我才发现，原来是我自己，不知不觉为神设定了一个时间的限制。神从未承诺过，在人们祈求、寻找、叩门后，他必定在一个月、一年、五年或者其他什么时间内“给他们”、“让他们寻见”、“给他们开门”。时间的主权在他的手中，不在我们的想象当中。这便成了我一个更新后的、更丰富的对神的先验、主观的认识。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以之后再有慕道友向我这样抱怨，我就知道怎样回答了：神确实应许‘叩门的，就给他开门’，但他并未应许开门的时刻表。所以如果你叩门了一个月还没有开，那就继续再叩一个月；如果你寻求了一年还没有寻见，那就再寻找一年。最重要的是，不要放弃。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我自己在读威廉·博德恩的事迹中，更新了对神的认识，也是同样的过程。他的死让我困惑于神的呼召，但其实圣经对神的主权早有清晰的启示，无论是死人、活人、天上的、地下的，无不在他的掌管之下。所以他使用活人，也使用死人。大家看，如果我不把心屈服在圣经之下去调整对神的认识，那很可能得出的结论就是神不过是戏弄了博德恩。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("刚才我提到的那位因夫妻矛盾而离开神的女士，她不愿把自己的心屈服在圣经之下，因此也无法认识到：神是一位要求她舍弃一切来跟随的主，也是一位凭自己的时间和方式来改变她丈夫的主。所以，当她在经验中认识的神与她想象中的神不一样，她就无法正确做出调整，最终跌倒了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("保罗华许讲道后认识的那位老姐妹也一样。如果她不愿把自己的心屈服在圣经之下，她就会拒绝按照在那一天所听到的信息，去调整她原先那个对神的、主观的、想象出来的认识，那么她每个礼拜天去教会，就不过是在重复敬拜一个自己制造出来的偶像。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("还有更极端的例子。我昨天正好在b站上看到一个介绍摩门教的视频。里面讲到摩门教的起源。它的创始人约瑟夫·史密斯声称自己在14岁，也就是1820年，在美国纽约州树林祷告的时候看见了天使。天使告诉他，所有教会都是错的，现在的圣经都是有缺失的，于是给了他一些金叶子，让他翻译出来，就是所谓的《摩门经》。伊斯兰教的创立，其实也是类似的故事。只不过把地点从森林变成了石洞。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们姑且承认约瑟夫或者穆罕穆德的经验是真实的。那么此时他们有了一个新的、从经验而来的认识。这个认识显然与他们之前先验中的、主观上的对神的认识有差异。但由于他们放弃了圣经的界限，“完全”从自身的这些经验、经历中去重构自己心中神的样子，最终就是误入歧途，走火入魔。灵界是真实存在的，所以一些奇奇怪怪的经历，在每个人的信仰道路上都可能出现，这些经验可以用来调整我们对神的认识，但必须经受圣经的检验，不能逾越圣经的界限。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，今天我们讲的这篇信息，可能会比较抽象，所以我举的例子多一些。希望大家能理解这个对神的认识过程，并且能在自己的信仰旅程中不断实践。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果让我用一句话简单总结这个过程，就是“在圣经的标准和界限内，用你真实的生命经历，去不断丰富、深化，甚至纠正你心中神的形象。”这是一个不断循环的过程。而你对神的认识，就在这个循环中变得更加清晰、丰盛、准确、真实。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("要进入到这个过程中，你的心需要具备三个基本的条件：第一，是降服于圣经的权威。就是以圣经为终极标尺，来衡量你一切的经历与认知。第二，有意识地把自己的经验与神联系在一起。你不再将生活经历视为与信仰无关的过程，而是主动地去思想其中所体现的神的属性与作为。第三，是持守一颗谦卑的心。你承认自己目前对神的认识仍是不完全的、可以被更新的、被重塑的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第一点——也就是你承认圣经的权威——确保了在这个过程中不会走火入魔、步入歧途。它像轨道，防止我们“脱轨”，陷入偏差甚至异端当中。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第二点和第三点——也就是主动地在经验中去获得对神的认识、谦卑地承认自己原有的观念科以被调整——共同决定了你在这个循环中前进的速度与深度。你越是主动地把每天的经验与神联系在一起，你就能更多地从这些经验中获得对神的认识；同时，你越谦卑自己，你就会越容易让这些经验中的认识去更新甚至挑战自己那主观的、先验的认识。于是，这个“认识-经历-调整-再认识-再经历-再调整”的循环转动得就越快、越深入。你每一次的经验，都在让你主观上所认识的神变得更丰富、更立体、更真实。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而这就会给我们带来智慧与生命的改变。正如《箴言》9:10所说：“认识至圣者便是聪明。”你对神的认识每增加一分，祂对你的生命的塑造也就更深一分。所以这不仅是知识的积累，更是生命被真理浸润、更新的过程。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("最后，我还是想以一个偈子，来总结这个过程，帮助大家记忆：“以经为尺，以行调知，周而复始，大道可识。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“以经为尺”，是说我们的标杆和边界是神的话；“以行调知”，是说我们要用生活中的实际经历，来不断调整、丰富我们对神的认知；这个“认识-经历-调整-再认识-再经历-再调整”的过程“周而复始”，我们便在恩典中，越来越接近那真正的“大道”——我们就可以有对神自己更清晰、更丰盛的、更真实、更全面、更客观的认识。")])],1)])}),[],!1,null,null,null);s.default=n.exports}}]);